public class Test {
    public static void main(String[] a) throws Exception {
        checkStream("EventLog.java", "namesAfter");
        java.util.List<EventLog.Event> ev = java.util.List.of(
            new EventLog.Event("launch", java.time.LocalDate.of(2026, 5, 1)),
            new EventLog.Event("kickoff", java.time.LocalDate.of(2026, 1, 10)),
            new EventLog.Event("review", java.time.LocalDate.of(2026, 3, 2)));
        if (!(EventLog.namesAfter(ev, java.time.LocalDate.of(2026, 3, 1)).equals(java.util.List.of("launch", "review")))) throw new AssertionError("namesAfter");
        if (!(EventLog.namesAfter(ev, java.time.LocalDate.of(2026, 5, 1)).isEmpty())) throw new AssertionError("cutoff is exclusive");
        System.out.println("PASS");
    }

    static String methodBody(String file, String name) throws Exception {
        String src = new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get(file)));
        java.util.regex.Matcher m = java.util.regex.Pattern
            .compile("\\b" + name + "\\s*\\([^)]*\\)\\s*\\{").matcher(src);
        if (!m.find()) throw new AssertionError("method " + name + " not found");
        int start = m.end() - 1, depth = 0;
        for (int i = start; i < src.length(); i++) {
            char c = src.charAt(i);
            if (c == '{') depth++;
            else if (c == '}' && --depth == 0) return src.substring(start, i + 1);
        }
        throw new AssertionError("unbalanced braces");
    }

    static void checkStream(String file, String name) throws Exception {
        String body = methodBody(file, name);
        if (!body.contains(".stream()")) throw new AssertionError(name + " does not use .stream()");
        if (java.util.regex.Pattern.compile("\\bfor\\s*\\(").matcher(body).find())
            throw new AssertionError(name + " still contains a for loop");
    }
}
